    const weightConversion = parseFloat(it.weight_conversion) || 0;
    it.packing_qty = Math.round((qtyToPick / packingConversion) * 1000) / 1000;
    it.net_weight = Math.round(qtyToPick * weightConversion * 1000) / 1000;
