      bundleRow.pending_process_qty = 0;
      continue;
    }
    if (parts.length === 0) continue;
    const worst = parts.reduce((w, part) => {
      const planned = parseFloat(part.qty_to_pick) || 0;
      const left = parseFloat(part.pending_process_qty) || 0;
